func greet(_ name: String?) {
    guard let name else {
        print("Hello, stranger")
        return
    }
    print("Hello, \(name)")
}

let input: String? = "Swift"
if let input {
    greet(input)
}

enum LoadState {
    case idle
    case loading(progress: Double)
    case failed(message: String)
}

func describe(_ state: LoadState) -> String {
    switch state {
    case .idle: "Waiting"
    case .loading(let progress): "Loading \(Int(progress * 100))%"
    case .failed(let message): "Error: \(message)"
    }
}

struct PointValue { var x = 0 }
final class PointRef { var x = 0 }

var a = PointValue()
var b = a
b.x = 10
print(a.x) // 0: b is a copy

let c = PointRef()
let d = c
d.x = 10
print(c.x) // 10: same object

final class Owner {
    var pet: Pet?
    deinit { print("Owner freed") }
}

final class Pet {
    weak var owner: Owner? // weak breaks the cycle
    deinit { print("Pet freed") }
}

var owner: Owner? = Owner()
owner?.pet = Pet()
owner?.pet?.owner = owner
owner = nil // both deinits run

func fetchUser(id: Int) async throws -> String {
    try await Task.sleep(for: .seconds(1))
    return "User \(id)"
}

Task {
    async let first = fetchUser(id: 1)
    async let second = fetchUser(id: 2)
    let users = try await [first, second]
    print(users)
}
